window.kbPageData["views/entry/k-9a8a45ceb5950828"] = {"key":"entry/k-9a8a45ceb5950828","state":{"route":"entry/k-9a8a45ceb5950828"},"node":{"id":"k-9a8a45ceb5950828","mode":"k","title":"习近平强军思想","type":"观点与论证","domain":"军事","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["军事"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"1.习近平强军思想\n2017 年 10 月，党的十九大把习近平强军思想写入党章，确立习近平强军思想在国防和\n军队建设中的指导地位。\n习近平强军思想的主要内容可以概括为“十一个明确”：①明确党对人民军队的绝对领\n导是人民军队建军之本、强军之魂；②明确强国必须强军，巩固国防和强大人民军队是新时\n代坚持和…","sources":[{"id":"0635ac740211e691","label":"习近平强军思想","topic":"发展与治理","category":"非时政","text":"1.习近平强军思想\n2017 年 10 月，党的十九大把习近平强军思想写入党章，确立习近平强军思想在国防和\n军队建设中的指导地位。\n习近平强军思想的主要内容可以概括为“十一个明确”：①明确党对人民军队的绝对领\n导是人民军队建军之本、强军之魂；②明确强国必须强军，巩固国防和强大人民军队是新时\n代坚持和发展中国特色社会主义、实现中华民族伟大复兴的战略支撑；③明确党在新时代的\n强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，到 2027 年实现建军一百\n年奋斗目标，到 2035 年基本实现国防和军队现代化，到本世纪中叶把人民军队建成世界一\n流军队；④明确军队是要准备打仗的，必须聚焦能打仗、打胜仗，扭住强敌对手；⑤明确推\n进强军事业必须坚持政治建军、改革强军、科技强军、人才强军、依法治军；⑥明确改革是\n强军的必由之路；⑦明确科技是核心战斗力；⑧明确强军之道要在得人；⑨明确依法治军是\n我们党建军治军基本方式；⑩明确军民融合发展是兴国之举、强军之策；⑪明确作风优良是\n我军鲜明特色和政治优势。","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":54,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-9a8a45ceb5950828":[]}};
